set -eu
base="${BATTEN_RELEASES:-https://github.com/button-inc/batten}"
fail() {
	echo "install.sh: $1" >&2
	exit "${2:-2}"
}
os=$(uname -s)
arch=$(uname -m)
case "$arch" in
x86_64 | amd64) arch=x86_64 ;;
aarch64 | arm64) arch=aarch64 ;;
*) fail "no release for $os/$arch" 1 ;;
esac
case "$os" in
Linux)
	libc=gnu
	for loader in /lib/ld-musl-*; do
		[ -e "$loader" ] && libc=musl
	done
	target="$arch-unknown-linux-$libc"
