get() {
	got=$(curl -sSL --connect-timeout 20 --max-time 600 --retry 3 --retry-delay 1 \
		-o "$2" -w '%{http_code} %{url_effective}' "$1") || true
	case "$got" in
	200\ *) ;;
	404\ *) fail "could not download $1: $got" "${3:-2}" ;;
	*) fail "could not download $1: ${got:-000}" ;;
	esac
}
